function readLanguage(): Language {
  const saved = localStorage.getItem('jsa-language');
  return saved === 'हिन्दी' || saved === 'मराठी' ? saved : 'English';
}
function useLanguage() {
  const [language, setCurrentLanguage] = useState<Language>(readLanguage);
  useEffect(() => {
    const sync = () => setCurrentLanguage(readLanguage());
    window.addEventListener('jsa-language-change', sync);
    return () => window.removeEventListener('jsa-language-change', sync);
  }, []);
  useEffect(() => { document.documentElement.lang = language === 'हिन्दी' ? 'hi' : language === 'मराठी' ? 'mr' : 'en'; }, [language]);
  const setLanguage = (next: Language) => {
    localStorage.setItem('jsa-language', next);
    setCurrentLanguage(next);
    window.dispatchEvent(new Event('jsa-language-change'));
  };
  const t = (key: string) => {
    const english = key.includes(':') ? key.slice(key.indexOf(':') + 1) : key;
    return language === 'English' ? english : copy[language][key] ?? english;
  };
  return { language, setLanguage, t };
}

