export function SchemesPage() {
  const { t } = useLanguage();
  const [category,setCategory]=useState('Everyone'); const [age,setAge]=useState(''); const [stateName,setStateName]=useState(''); const [checked,setChecked]=useState(false); const [query,setQuery]=useState('');
  const filtered=useMemo(()=>schemeExamples.filter((s)=>(category==='Everyone'||s.category===category)&&`${s.title} ${s.description} ${s.keywords}`.toLowerCase().includes(query.toLowerCase())),[category,query]);
  return <div className="page-content">
    <PageHead eyebrow="Find a helpful starting point" title="Support that meets you here" description="Explore a few illustrative support categories and use the simple checker to think about what to ask next."/>
    <Caveat/>
    <section className="soft-card mt-5 p-5 sm:p-7"><div className="grid gap-6 lg:grid-cols-[1.1fr_.9fr] lg:items-center"><div><div className="eyebrow">{t('scheme:Quick private check')}</div><h2 className="mb-2 mt-2 font-display text-2xl font-extrabold">{t('scheme:What kind of support are you looking for?')}</h2><p className="mb-0 text-sm leading-6 text-[#758079]">This is a sample matching tool, not an official eligibility decision. No information leaves this browser.</p></div><form onSubmit={(e)=>{e.preventDefault();setChecked(true);}} className="grid gap-3 sm:grid-cols-2"><label className="text-xs font-bold text-[#586a61]">{t('scheme:Your age group')}<select className="field mt-2" value={age} onChange={(e)=>setAge(e.target.value)} data-testid="select-eligibility-age"><option value="">{t('scheme:Choose one')}</option><option>Under 18</option><option>18–29</option><option>30–59</option><option>60+</option></select></label><label className="text-xs font-bold text-[#586a61]">{t('scheme:State or union territory')}<input className="field mt-2" value={stateName} onChange={(e)=>setStateName(e.target.value)} placeholder={t('scheme:For example, Maharashtra')} data-testid="input-eligibility-state"/></label><button className="primary-btn flex items-center justify-center gap-2 sm:col-span-2" type="submit" data-testid="button-check-eligibility"><Search size={16}/> {t('common:Show sample starting points')}</button></form></div>{checked&&<div className="mt-5 rounded-xl border border-[#d9e8dc] bg-[#f1f7f0] p-4" role="status" data-testid="status-eligibility-result"><div className="flex gap-2 text-sm font-bold text-[#236b5c]"><CheckCircle2 size={18}/>{t('common:A few places to begin')}</div><p className="mb-3 mt-2 text-xs leading-5 text-[#65776c]">Based on the details you entered{age?` (${age})`:''}{stateName?` in ${stateName}`:''}, explore the examples below. This is not a confirmed match or eligibility result; check with an official source.</p><div className="flex flex-wrap gap-2">{schemeExamples.filter((s)=>!age?true:age==='60+'?s.category==='Senior citizens':s.category!=='Senior citizens').slice(0,3).map((s)=><span key={s.title} className="pill">{s.title}</span>)}</div></div>}</section>
    <div className="mt-9 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><div className="eyebrow">{t('scheme:Explore by need')}</div><h2 className="mb-0 mt-2 font-display text-2xl font-extrabold">{t('scheme:A few places to begin')}</h2></div><label className="relative block sm:w-64"><Search size={16} className="absolute left-3 top-3.5 text-[#85918a]"/><input value={query} onChange={(e)=>setQuery(e.target.value)} placeholder={t('common:Search examples')} className="field pl-9" aria-label={t('common:Search support examples')} data-testid="input-search-schemes"/></label></div>
    <div className="mt-4 flex gap-2 overflow-x-auto pb-2">{['Everyone','Students','Job seekers','Women','Senior citizens'].map((c)=><button key={c} onClick={()=>setCategory(c)} className={`whitespace-nowrap rounded-full px-4 py-2 text-xs font-bold ${category===c?'bg-[#267a69] text-white':'border border-[#e5dfd3] bg-[#fffefa] text-[#68776e] hover:bg-[#eef2eb]'}`} type="button" data-testid={`filter-scheme-${c.toLowerCase().replaceAll(' ','-')}`}>{t(`filter:${c}`)}</button>)}</div>
    <div className="mt-4 grid gap-4 md:grid-cols-2">{filtered.map((scheme)=><article key={scheme.title} className="soft-card lift p-5 sm:p-6" data-testid={`card-scheme-${scheme.category.toLowerCase().replaceAll(' ','-')}`}><div className="flex items-start justify-between"><span className="grid h-12 w-12 place-items-center rounded-2xl" style={{background:scheme.tone,color:scheme.iconColor}}><scheme.icon size={22}/></span><span className="pill">{scheme.tag}</span></div><div className="mt-5"><h3 className="mb-1 font-display text-xl font-extrabold">{scheme.title}</h3><p className="mb-4 text-sm leading-6 text-[#758079]">{scheme.description}</p><div className="flex items-center justify-between border-t border-[#eee8dc] pt-4"><span className="text-xs text-[#77837b]">For: {scheme.audience}</span><button type="button" className="inline-flex items-center gap-1 text-xs font-bold text-[#267a69]" onClick={()=>setChecked(true)} data-testid={`button-check-${scheme.category.toLowerCase().replaceAll(' ','-')}`}>{t('common:Check example')} <ArrowRight size={14}/></button></div></div></article>)}</div>
    {filtered.length===0&&<div className="soft-card mt-4 p-10 text-center"><Search size={26} className="mx-auto text-[#94a098]"/><h3 className="mb-1 mt-3 font-display text-lg font-extrabold">No examples found</h3><p className="mb-0 text-sm text-[#758079]">Try a different phrase or clear the category filter.</p><button className="secondary-btn mt-4" onClick={()=>{setCategory('Everyone');setQuery('');}} type="button" data-testid="button-clear-scheme-filters">{t('common:Clear filters')}</button></div>}
  </div>;
}

